    return (arr[lb], arr[lb])
  elif (ub - lb == 1):  #
    if (arr[lb] < arr[ub]):
      return (arr[lb], arr[ub])
    else:
      return (arr[ub], arr[lb])
  else:  #
    mid = (lb + ub) // 2
    [l_sub_min, l_sub_max] = minmax(arr, lb, mid)
    [r_sub_min, r_sub_max] = minmax(arr, mid + 1, ub)

    #
    if (l_sub_min < r_sub_min):
      mini = l_sub_min
    else:
      mini = r_sub_min

    if (l_sub_max < r_sub_max):
      maxi = r_sub_max
    else:
      maxi = l_sub_max

    return (mini, maxi)
